create table if not exists mastering_master(entity_id char(36) primary key, changed_file bigint not null default 0, body text not null, created_at timestamptz not null default clock_timestamp());
create index if not exists mastering_master_changed on mastering_master(changed_file, entity_id);
create table if not exists mastering_file(file_key char(64) primary key, records bigint not null);
create table if not exists mastering_delivery(file_key char(64) not null, source_code varchar(64) not null, records bigint not null, repeated bigint not null, deferred bigint not null, primary key(file_key, source_code));
create table if not exists mastering_identifier(namespace varchar(32) not null, value varchar(128) not null, entity_id char(36) not null, primary key(namespace, value, entity_id));
create index if not exists mastering_identifier_entity on mastering_identifier(entity_id);
create table if not exists mastering_record(assertion_id varchar(128) primary key, subject varchar(255) not null, entity_id char(36), bound_id char(36), source_code varchar(64) not null, lei varchar(32), body text not null);
create index if not exists mastering_record_entity on mastering_record(entity_id);
create index if not exists mastering_record_subject on mastering_record(subject);
create index if not exists mastering_record_lei on mastering_record(lei);
create table if not exists mastering_name_key(role varchar(16) not null, value varchar(64) not null, subject varchar(255) not null, primary key(role, value, subject));
create index if not exists mastering_name_key_subject on mastering_name_key(subject);
create table if not exists mastering_review(subject varchar(255) not null, reason varchar(64) not null, assertion_id varchar(128), open_review bigint not null, primary key(subject, reason));
create table if not exists mastering_decision(decision_id char(64) primary key, operation varchar(16) not null, left_id varchar(255), right_id varchar(255), body text not null);
create index if not exists mastering_decision_left on mastering_decision(operation, left_id);
create table if not exists mastering_withheld(subject varchar(255) not null, namespace varchar(32) not null, raw varchar(128) not null, primary key(subject, namespace, raw));
create table if not exists mastering_deferred(deferred_id varchar(128) primary key, source_code varchar(64) not null, reason varchar(64) not null, blocking bigint not null, body text not null);
create table if not exists mastering_lookup(token char(64) not null, entity_id char(36) not null, primary key(token, entity_id));
create index if not exists mastering_lookup_entity on mastering_lookup(entity_id);
create table if not exists mastering_lookup_progress(pin char(64) primary key, changed_file bigint not null, entity_id varchar(36) not null);
